/** One DMX mode and how many channels it takes. */
export type FixtureMode = { name: string; channels: number };

export type FixtureDef = {
  brand: string;
  model: string;
  group: string;
  modes: FixtureMode[];
  /** Maximum power in watts, when the source gives it */
  watts?: number;
  /** Weight in kilograms, when the source gives it */
  kg?: number;
  source: string;
  note?: string;
};

